const decoysByCategory: Record<string, string[][]> = {
  'History & inventions': [['A rival patent wins the market|Same era', 'A factory changes its logo|Same era'], ['A museum preserves an unrelated prototype|Later archive', 'A competing material becomes fashionable|Same era']],
  'Science & accidents': [['A nearby experiment produces a different result|Same era', 'A laboratory closes for renovations|Same era'], ['A new measuring instrument is announced|Same era', 'A rival theory gains temporary attention|Same era']],
  Medicine: [['A diagnostic test becomes popular|Same era', 'A hospital expands its waiting room|Same era'], ['A different drug is trialed|Same era', 'A medical textbook changes its diagram|Same era']],
  'Technology & computing': [['A larger machine keeps the old workflow|Same era', 'A competing standard gains a short lead|Same era'], ['A hardware company changes its logo|Same era', 'A research paper remains unpublished|Same era']],
  'Internet culture': [['A platform adds a new privacy setting|Same era', 'A forum changes its homepage|Same era'], ['A competing file format appears|Same era', 'A niche community keeps the older habit|Same era']],
  'Food & everyday': [['A nearby recipe becomes fashionable|Same era', 'A kitchen tool changes shape|Same era'], ['A restaurant opens a new dining room|Same era', 'A different ingredient is rationed|Same era']],
  'Design & work': [['A packaging color is redesigned|Same era', 'A competing office material is tested|Same era'], ['A trade show displays a similar object|Same era', 'A factory adopts a separate safety rule|Same era']],
  'Music & culture': [['A label changes the album artwork|Same era', 'A different instrument tops the charts|Same era'], ['A radio station shortens the song|Same era', 'A new magazine reviews the scene|Same era']],
  'Nature & society': [['A city commissions a commemorative statue|Same era', 'A separate reform remains local|Same era'], ['A weather pattern changes the next season|Same era', 'A committee publishes a report without action|Same era']],
}

const relationshipDefaults: Relationship[] = ['Contributed', 'Enabled', 'Inspired', 'Popularized']
const tones = ['coral', 'blue', 'gold', 'mint', 'ink']
const icons = ['✦', '◌', '⌁', '◎', '↗']
const detailTemplates = [
  'The starting condition that makes this case worth following.',
  'A pressure, observation, or constraint changes what is possible next.',
  'A practical experiment turns the pressure into a workable path.',
  'The idea travels beyond its first setting and gathers new uses.',
  'The ripple is now familiar, even though its origin is easy to miss.',
]

const parseEvent = (seedData: CaseSeed, raw: string, index: number): Event => {
  const [title, year = 'Historical record'] = raw.split('|')
  return { id: `${seedData.id}-event-${index + 1}`, title, detail: detailTemplates[index], year, icon: icons[index % icons.length], tone: tones[index % tones.length] }
}

const makeChoice = (event: Event, correct: boolean, whyWrong?: string): Choice => ({ ...event, correct, whyWrong })

const buildPuzzle = (seedData: CaseSeed, index: number): Puzzle => {
  const events = seedData.chain.map((raw, eventIndex) => parseEvent(seedData, raw, eventIndex))
  const decoySets = decoysByCategory[seedData.category] ?? decoysByCategory['History & inventions']
  const relationships = seedData.relationships ?? relationshipDefaults
  const steps = events.slice(0, -1).map((from, stepIndex) => {
    const to = events[stepIndex + 1]
    const relation = relationships[stepIndex] ?? 'Contributed'
    const decoys = decoySets[stepIndex % decoySets.length].map((raw, decoyIndex) => parseEvent(seedData, `${raw}|${raw.split('|')[1] ?? 'Same era'}`, stepIndex + decoyIndex + 1))
    const rejection = (event: Event) => `${event.title} is a believable nearby development, but the source trail does not show it as the bridge from ${from.title.toLowerCase()} to ${to.title.toLowerCase()}.`
    const choices = [makeChoice(to, true), ...decoys.map((event) => makeChoice({ ...event, id: `${seedData.id}-decoy-${stepIndex + 1}-${event.id}` }, false, rejection(event)))]
    const rotated = choices.slice((index + stepIndex) % choices.length).concat(choices.slice(0, (index + stepIndex) % choices.length))
    return {
      id: `${seedData.id}-link-${stepIndex + 1}`,
      question: `How did ${from.title.toLowerCase()} open the path to the next clue?`,
      bridge: `${relation} · ${from.title} changed the conditions around ${to.title.toLowerCase()}; the source trail treats this as a ${relation.toLowerCase()} link, not a single-cause certainty.`,
      relationship: relation,
      from: from.id,
      to: to.id,
      choices: rotated,
      hint: `Look for the event that changes what people can do after ${from.title.toLowerCase()}.`,
      source: seedData.source,
    }
  })
  const hook = `${events[0].title}. ${events[4].title}. Follow the documented turns in between.`
  return {
    id: seedData.id,
    number: 200 + index,
    category: seedData.category,
    difficulty: index % 7 === 0 ? 'Hard' : index % 3 === 0 ? 'Standard' : 'Easy',
    duration: '2–4 min',
    hook,
    question: seedData.question,
    start: events[0],
    ending: events[4],
    steps,
    takeaway: `This case follows how ${events[0].title.toLowerCase()} contributed to ${events[4].title.toLowerCase()} through several smaller, documented changes.`,
    sources: [seedData.source],
    accent: ['#e26e5b', '#d9a441', '#5f9d8d', '#6d8e9e', '#b978a4'][index % 5],
  }
}

export const expandedPuzzles: Puzzle[] = caseSeeds.map(buildPuzzle)
